import React, { useRef, useEffect, useState, useCallback } from 'react';
import { createPortal } from 'react-dom';
import { Icon } from '../icons.jsx';
import { ColorButton } from './ColorButton.jsx';
import { sanitizeHtml } from '../../lib/sanitizeHtml.js';
import { fragToPlain, plainToHtml } from '../../lib/rteClipboard.js';

/* ──────────────────────────────────────────────────────────────
   RichTextEditor — contenteditable rich-text surface with a
   functional toolbar (execCommand based) and {{variable}} chips.

   Powers both the email-template body and the email signature.

   Props:
     initialHtml  string  — content to load once on mount
     onChange     (html)  — emits stored-format HTML (chips → {{var}})
     variables    [{name}]— available variables for the insert menu
     singleLine   bool    — one-line mode: no toolbar, Enter disabled,
                            emits plain text (for the subject field)
     size         'sm'|'md' — overall density. 'sm' = compact toolbar,
                            tighter padding, smaller text. Default 'md'.
     minHeight    number  — body min-height override (full mode); when
                            omitted, falls back to the size's default
     placeholder  string
─────────────────────────────────────────────────────────────── */

/* ── Density presets — every size-dependent measurement lives here so
      'sm' and 'md' stay in lockstep. ──────────────────────────── */
const SIZES = {
  sm: {
    btnW: 22, btnH: 21, icon: 11, sepH: 13, toolbarPad: '3px 5px',
    pad: '10px 12px', font: 10.5, minHeight: 120,
    slPad: '6px 9px', slFont: 11,
    varH: 21, varFont: 10, varIcon: 9,
    phFull: { top: 10, left: 13, font: 10.5 },
    phLine: { top: 6,  left: 10, font: 11 },
  },
  md: {
    btnW: 26, btnH: 24, icon: 12, sepH: 14, toolbarPad: '4px 6px',
    pad: '14px', font: 11.5, minHeight: 160,
    slPad: '7px 10px', slFont: 12,
    varH: 24, varFont: 10.5, varIcon: 10,
    phFull: { top: 14, left: 14, font: 11.5 },
    phLine: { top: 7,  left: 10, font: 12 },
  },
};

/* ── Toolbar icons ──────────────────────────────────────────── */
const Ic = {
  bold:      p => <Icon {...p}><path d="M6 4h8a4 4 0 010 8H6zM6 12h9a4 4 0 010 8H6z"/></Icon>,
  italic:    p => <Icon {...p}><line x1="19" y1="4" x2="10" y2="4"/><line x1="14" y1="20" x2="5" y2="20"/><line x1="15" y1="4" x2="9" y2="20"/></Icon>,
  underline: p => <Icon {...p}><path d="M6 3v7a6 6 0 0012 0V3"/><line x1="4" y1="21" x2="20" y2="21"/></Icon>,
  strike:    p => <Icon {...p}><path d="M16 4H9a3 3 0 00-2.83 4M14 12a4 4 0 010 8H6"/><line x1="4" y1="12" x2="20" y2="12"/></Icon>,
  ul:        p => <Icon {...p}><line x1="8" y1="6" x2="21" y2="6"/><line x1="8" y1="12" x2="21" y2="12"/><line x1="8" y1="18" x2="21" y2="18"/><line x1="3" y1="6" x2="3.01" y2="6"/><line x1="3" y1="12" x2="3.01" y2="12"/><line x1="3" y1="18" x2="3.01" y2="18"/></Icon>,
  ol:        p => <Icon {...p}><line x1="10" y1="6" x2="21" y2="6"/><line x1="10" y1="12" x2="21" y2="12"/><line x1="10" y1="18" x2="21" y2="18"/><path d="M4 6h1v4M4 10h2M6 18H4c0-1 2-2 2-3s-1-1.5-2-1"/></Icon>,
  link:      p => <Icon {...p}><path d="M10 13a5 5 0 007 0l4-4a5 5 0 00-7-7l-1 1"/><path d="M14 11a5 5 0 00-7 0l-4 4a5 5 0 007 7l1-1"/></Icon>,
  alignL:    p => <Icon {...p}><line x1="17" y1="10" x2="3" y2="10"/><line x1="21" y1="6" x2="3" y2="6"/><line x1="21" y1="14" x2="3" y2="14"/><line x1="17" y1="18" x2="3" y2="18"/></Icon>,
  alignC:    p => <Icon {...p}><line x1="18" y1="10" x2="6" y2="10"/><line x1="21" y1="6" x2="3" y2="6"/><line x1="21" y1="14" x2="3" y2="14"/><line x1="18" y1="18" x2="6" y2="18"/></Icon>,
  alignR:    p => <Icon {...p}><line x1="21" y1="10" x2="7" y2="10"/><line x1="21" y1="6" x2="3" y2="6"/><line x1="21" y1="14" x2="3" y2="14"/><line x1="21" y1="18" x2="7" y2="18"/></Icon>,
  bolt:      p => <Icon {...p}><path d="M13 2L3 14h9l-1 8 10-12h-9l1-8z"/></Icon>,
  clear:     p => <Icon {...p}><path d="M4 7h16M10 11v6M14 11v6M6 7l1 13h10l1-13"/></Icon>,
};

/* ── Injected stylesheet (chips, placeholder, content defaults) ── */
const STYLE_ID = '__gb-rte-style';
function ensureStyle() {
  if (typeof document === 'undefined' || document.getElementById(STYLE_ID)) return;
  const el = document.createElement('style');
  el.id = STYLE_ID;
  el.textContent = `
    .gb-rte-content { outline: none; scrollbar-width: thin; scrollbar-color: var(--gb-border-default) transparent; }
    .gb-rte-content p { margin: 0 0 8px; }
    .gb-rte-content p:last-child { margin-bottom: 0; }
    .gb-rte-content a { color: var(--gb-brand-label); }
    .gb-rte-content ul, .gb-rte-content ol { margin: 0 0 8px; padding-left: 22px; }
    .gb-rte-slash-status {
      display: inline-flex; align-items: center; vertical-align: baseline;
      margin: 0 2px; padding: 1px 7px; border-radius: 999px !important;
      border: 1px solid var(--gb-brand-tint-border);
      background: var(--gb-brand-tint-soft); color: var(--gb-brand-label);
      font-family: var(--gb-font-mono); font-size: .9em; font-weight: 700;
      user-select: all;
    }
    .gb-rte-slash-status[data-state="loading"]::before {
      content: ''; width: 7px; height: 7px; margin-right: 5px;
      border: 1.5px solid currentColor; border-right-color: transparent;
      border-radius: 50%; animation: gb-rte-slash-spin .7s linear infinite;
    }
    .gb-rte-slash-status[data-state="error"] {
      border-color: var(--gb-error-tint-border); background: var(--gb-error-tint-soft);
      color: var(--gb-error-fg);
    }
    @keyframes gb-rte-slash-spin { to { transform: rotate(360deg); } }
    /* Thin themed scrollbars on RTE — fixes the chunky native bar that
       appears on long single-line subjects and tall bodies. */
    .gb-rte-content::-webkit-scrollbar { width: 6px; height: 6px; }
    .gb-rte-content::-webkit-scrollbar-track { background: transparent; }
    .gb-rte-content::-webkit-scrollbar-thumb {
      background: var(--gb-border-default); border-radius: 6px !important;
    }
    .gb-rte-content::-webkit-scrollbar-thumb:hover { background: var(--gb-border-strong); }
    /* Matches BodyVar.jsx (size 'md') — the canonical body-content
       variable chip: two-part pill with name + clickable lightning bolt,
       divider between. Brand-colored at rest (resolution state isn't
       known at chip-render time inside contenteditable). */
    .gb-rte-chip {
      display: inline-flex; align-items: stretch; vertical-align: baseline;
      margin: 0 1px; border-radius: var(--gb-r-sm) !important; overflow: hidden;
      border: 1px solid var(--gb-brand-tint-border);
      background: var(--gb-brand-tint-soft);
      line-height: 1.4;
      user-select: all;
    }
    .gb-rte-chip-name {
      padding: 0 6px;
      font-family: var(--gb-font-mono);
      /* Match surrounding text — chip total height ≈ RTE line-height,
         so chips no longer push the line taller than other text. */
      font-size: inherit; font-weight: 600;
      color: var(--gb-brand-label);
      cursor: default;
    }
    .gb-rte-chip-bolt {
      padding: 0 4px;
      border-left: 1px solid var(--gb-brand-tint-border);
      color: var(--gb-brand-label);
      display: inline-flex; align-items: center;
      cursor: pointer;
      opacity: 0.55;
      transition: opacity .12s, background .12s;
    }
    .gb-rte-chip-bolt svg { display: block; width: 0.9em; height: 0.9em; }
    .gb-rte-chip:hover .gb-rte-chip-bolt {
      opacity: 1;
      background: color-mix(in srgb, var(--gb-brand-label) 13%, transparent);
    }
    /* OR-block chip — a pipe-separated placeholder renders as two
       named halves sharing one pill, divided by a slanted seam.
       Two-shade tint signals the priority-pick semantic: the first
       half is the preferred value, the second is the fallback. */
    .gb-rte-chip-or {
      display: inline-flex; align-items: stretch; vertical-align: baseline;
      margin: 0 1px; border-radius: var(--gb-r-sm) !important; overflow: hidden;
      border: 1px solid var(--gb-brand-tint-border);
      line-height: 1.4;
      user-select: all;
    }
    .gb-rte-chip-or-half {
      padding: 0 6px;
      font-family: var(--gb-font-mono);
      font-size: inherit; font-weight: 600;
      color: var(--gb-brand-label);
      cursor: default;
      position: relative;
    }
    .gb-rte-chip-or-half.first {
      background: var(--gb-brand-tint-soft);
      padding-right: 9px;
      clip-path: polygon(0 0, 100% 0, calc(100% - 6px) 100%, 0 100%);
    }
    .gb-rte-chip-or-half.second {
      background: color-mix(in srgb, var(--gb-brand-label) 18%, transparent);
      padding-left: 9px;
      margin-left: -6px;
      clip-path: polygon(6px 0, 100% 0, 100% 100%, 0 100%);
    }
    .gb-rte-chip-or .gb-rte-chip-bolt {
      padding: 0 4px;
      border-left: 1px solid var(--gb-brand-tint-border);
      color: var(--gb-brand-label);
      display: inline-flex; align-items: center;
      cursor: pointer;
      opacity: 0.55;
      transition: opacity .12s, background .12s;
    }
    .gb-rte-chip-or:hover .gb-rte-chip-bolt {
      opacity: 1;
      background: color-mix(in srgb, var(--gb-brand-label) 13%, transparent);
    }
    /* Inline-attachment block — a scalable, movable image placeholder.
       Renders at the variable's configured width; the corner handle drags
       to resize (persisted onto the var so the sent <img> matches). The
       block is contenteditable=false so it cuts/pastes/drags as one unit. */
    .gb-rte-att {
      display: inline-flex; flex-direction: column; align-items: center; justify-content: center;
      vertical-align: bottom; position: relative; gap: 4px;
      margin: 2px; padding: 10px 8px; box-sizing: border-box;
      min-height: 64px;
      border: 1.5px dashed var(--gb-brand-tint-border);
      border-radius: var(--gb-r-md) !important;
      background: var(--gb-brand-tint-soft);
      color: var(--gb-brand-label);
      user-select: all; cursor: grab;
    }
    .gb-rte-att-label {
      font-family: var(--gb-font-mono); font-size: 10px; font-weight: 700;
      max-width: 100%; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
    }
    .gb-rte-att-size {
      font-size: 9px; font-weight: 600; opacity: .65;
    }
    .gb-rte-att-resize {
      position: absolute; right: -1px; bottom: -1px; width: 12px; height: 12px;
      border-radius: 3px 0 var(--gb-r-md) 0;
      background: var(--gb-brand-label); opacity: .55;
      cursor: nwse-resize;
    }
    .gb-rte-att:hover .gb-rte-att-resize { opacity: .9; }
    /* Attached-file chip — paperclip pill listed in the body (mirrors how a
       mail client lists attachments); invisible in the sent email. */
    .gb-rte-att-file {
      display: inline-flex; align-items: center; gap: 5px; vertical-align: baseline;
      margin: 0 1px; padding: 1px 8px;
      border-radius: var(--gb-r-pill) !important;
      border: 1px solid var(--gb-border-strong);
      background: var(--gb-fill-subtle);
      color: var(--gb-text-secondary);
      font-family: var(--gb-font-mono); font-size: 0.85em; font-weight: 600;
      line-height: 1.5; user-select: all;
    }
    .gb-rte-att-file svg { display: block; width: 0.85em; height: 0.85em; }
    .gb-rte-ph {
      position: absolute; pointer-events: none;
      color: var(--gb-text-ghost);
    }`;
  (document.head || document.documentElement).appendChild(el);
}

/* ── {{var}} ↔ chip conversion ──────────────────────────────────
   Each chip is a two-part pill: the name and a clickable lightning
   "smart options" button, divider between — mirrors BodyVar.
   `{{a|b}}` (OR-block) renders as a two-tone split pill — first
   variant in the lighter half, fallback in the darker half,
   separated by a slanted seam. The visual surfaces the
   "priority-then-fallback" semantic without needing a tooltip. */
const CHIP_BOLT =
  '<span class="gb-rte-chip-bolt"><svg viewBox="0 0 24 24" width="9" height="9" fill="currentColor"><path d="M13 2L3 14h9l-1 8 10-12h-9l1-8z"/></svg></span>';
function escapeHtml(s) {
  return String(s).replace(/[&<>"']/g, (c) => (
    c === '&' ? '&amp;' :
    c === '<' ? '&lt;' :
    c === '>' ? '&gt;' :
    c === '"' ? '&quot;' : '&#39;'
  ));
}
const CHIP_CLIP =
  '<svg viewBox="0 0 24 24" width="10" height="10" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M21.4 11.05l-9.19 9.19a6 6 0 01-8.49-8.49l9.19-9.19a4 4 0 015.66 5.66l-9.2 9.19a2 2 0 01-2.83-2.83l8.49-8.48"/></svg>';
function chipHTML(name, meta) {
  /* Attachment variables render as their placement, not a generic pill:
     - inline image → a scalable block placeholder at the configured width
       (corner handle drags to resize; the block moves as one unit);
     - attached file → a paperclip chip, like a mail client's attachment list.
     Both keep the hidden .gb-rte-chip-name span so stripChips round-trips
     them back to {{name}} unchanged. */
  const m = meta && meta[name];
  if (m && m.kind === 'attachment') {
    const a = m.attach || {};
    if ((a.mode || 'inline') === 'inline') {
      const w = Math.max(24, Math.min(600, Number(a.width) || 220));
      return `<span class="gb-rte-chip gb-rte-att" contenteditable="false" data-att="${escapeHtml(name)}" style="width:${w}px">`
        + `<span class="gb-rte-att-label">${CHIP_CLIP}&nbsp;${escapeHtml(a.filename || name)}</span>`
        + `<span class="gb-rte-att-size">${w}px · ${escapeHtml(a.align || 'left')}</span>`
        + `<span class="gb-rte-chip-name" style="display:none">{{${escapeHtml(name)}}}</span>`
        + `<span class="gb-rte-att-resize" title="Drag to resize"></span>`
        + `</span>`;
    }
    return `<span class="gb-rte-chip gb-rte-att-file" contenteditable="false">`
      + `${CHIP_CLIP}${escapeHtml(a.filename || name)}`
      + `<span class="gb-rte-chip-name" style="display:none">{{${escapeHtml(name)}}}</span>`
      + `</span>`;
  }
  /* Pipe → OR-block. We split on the FIRST pipe only — extra pipes
     in a 3+ candidate block flatten into the second half's label
     so the chip stays visually two-toned (the runtime renderer
     still respects all candidates in order; the chip is a
     simplified visual). */
  if (name.includes('|')) {
    const idx = name.indexOf('|');
    const first  = name.slice(0, idx).trim();
    const second = name.slice(idx + 1).trim();
    return `<span class="gb-rte-chip gb-rte-chip-or" contenteditable="false">`
      + `<span class="gb-rte-chip-or-half first">${escapeHtml(first)}</span>`
      + `<span class="gb-rte-chip-or-half second">${escapeHtml(second)}</span>`
      + `<span class="gb-rte-chip-name" style="display:none">{{${escapeHtml(name)}}}</span>`
      + CHIP_BOLT
      + `</span>`;
  }
  return `<span class="gb-rte-chip" contenteditable="false"><span class="gb-rte-chip-name">{{${escapeHtml(name)}}}</span>${CHIP_BOLT}</span>`;
}
function highlightVars(html, meta) {
  return String(html || '').replace(/\{\{\s*([^}]+?)\s*\}\}/g, (_, n) => chipHTML(n.trim(), meta));
}
function stripChips(html) {
  const tmp = document.createElement('div');
  tmp.innerHTML = html || '';
  tmp.querySelectorAll('.gb-rte-chip').forEach(s => {
    // Extract from the name span so the bolt SVG never leaks into storage.
    const nameEl = s.querySelector('.gb-rte-chip-name');
    s.replaceWith(document.createTextNode((nameEl || s).textContent || ''));
  });
  return tmp.innerHTML;
}


/* Plain text / newline body → HTML paragraphs (legacy templates). */
function normalizeInitial(html) {
  const s = String(html || '');
  if (s && !s.includes('<')) {
    return s.split('\n').map(l => (l.trim() ? `<p>${l}</p>` : '<p><br></p>')).join('');
  }
  return s;
}

/* ── Toolbar primitives ─────────────────────────────────────── */
function TBtn({ icon, active, onMouseDown, title: _title, sz }) {
  return (
    <button
      type="button" onMouseDown={onMouseDown}
      style={{
        width: sz.btnW, height: sz.btnH, borderRadius: 4, border: 'none', cursor: 'pointer',
        background: active ? 'var(--gb-brand-tint-medium)' : 'transparent',
        color: active ? 'var(--gb-brand-label)' : 'var(--gb-text-tertiary)',
        display: 'inline-flex', alignItems: 'center', justifyContent: 'center',
      }}
    >
      {React.cloneElement(icon, { size: sz.icon })}
    </button>
  );
}
const Sep = ({ sz }) => (
  <div style={{ width: 1, height: sz.sepH, background: 'var(--gb-border-subtle)', margin: '0 3px' }} />
);

export function RichTextEditor({
  initialHtml, onChange, onChipClick, variables = [], singleLine = false,
  size = 'md', minHeight, placeholder = '', onAttachmentResize,
  onSlashQueryChange, onSlashExecute, onSlashNavigate, onSlashCancel,
  // `bare` = no outer border/radius/background — the editor blends into a
  // parent that already frames it (e.g. the compose modal), instead of
  // drawing a redundant nested box.
  bare = false,
}) {
  const sz       = SIZES[size] || SIZES.md;
  const bodyMinH = minHeight != null ? minHeight : sz.minHeight;

  const ref        = useRef(null);
  const savedRange = useRef(null);
  const [marks,     setMarks]     = useState({});
  const [empty,     setEmpty]     = useState(true);
  const [varMenu,   setVarMenu]   = useState(false);
  const varBtnRef = useRef(null);
  // Last-picked text + highlight colors — drive the toolbar swatches so
  // the buttons reflect the current choice instead of a static muted color.
  const [textColor, setTextColor] = useState('#7db82a');
  const [bgColor,   setBgColor]   = useState('#fff170');
  const slashRef = useRef(null);
  const slashSuppressedRef = useRef(false);

  /* name → {kind, attach} for attachment variables — drives the chip
     renderer (inline block vs paperclip pill). Kept in a ref so the
     mount-once content load reads the freshest map without re-running. */
  const varMetaRef = useRef({});
  varMetaRef.current = (variables || []).reduce((m, v) => {
    if (v && typeof v === 'object' && v.kind === 'attachment') m[v.name] = v;
    return m;
  }, {});

  /* Load content once on mount. */
  useEffect(() => {
    ensureStyle();
    const el = ref.current;
    if (!el) return;
    el.innerHTML = highlightVars(sanitizeHtml(normalizeInitial(initialHtml)), varMetaRef.current);
    setEmpty(!el.textContent.trim());
  }, []); // eslint-disable-line react-hooks/exhaustive-deps

  /* Emit stored-format content to the parent. */
  const emit = useCallback(() => {
    const el = ref.current;
    if (!el || !onChange) return;
    onChange(singleLine ? (el.textContent || '') : sanitizeHtml(stripChips(el.innerHTML)));
  }, [onChange, singleLine]);

  const refreshMarks = useCallback(() => {
    if (singleLine) return;
    try {
      setMarks({
        bold:      document.queryCommandState('bold'),
        italic:    document.queryCommandState('italic'),
        underline: document.queryCommandState('underline'),
        strike:    document.queryCommandState('strikeThrough'),
      });
    } catch { /* queryCommandState can throw without a selection */ }
  }, [singleLine]);

  const saveSelection = useCallback(() => {
    const sel = window.getSelection();
    if (sel && sel.rangeCount && ref.current && ref.current.contains(sel.anchorNode)) {
      savedRange.current = sel.getRangeAt(0).cloneRange();
    }
  }, []);

  function exec(cmd, value) {
    ref.current?.focus();
    if (savedRange.current) {
      const sel = window.getSelection();
      sel.removeAllRanges();
      sel.addRange(savedRange.current);
    }
    try {
      // styleWithCSS makes foreColor / hiliteColor write inline `style=`
      // attrs instead of legacy <font> tags — without it, hiliteColor is
      // a no-op in Chrome.
      document.execCommand('styleWithCSS', false, true);
      document.execCommand(cmd, false, value ?? null);
    } catch { /* noop */ }
    saveSelection();
    refreshMarks();
    setEmpty(!ref.current.textContent.trim());
    emit();
  }

  function insertVariable(name) {
    setVarMenu(false);
    ref.current?.focus();
    if (savedRange.current) {
      const sel = window.getSelection();
      sel.removeAllRanges();
      sel.addRange(savedRange.current);
    }
    document.execCommand('insertHTML', false, chipHTML(name, varMetaRef.current) + ' ');
    saveSelection();
    setEmpty(false);
    emit();
  }

  /* Live-convert a just-typed {{var}} into a chip as soon as the closing }}
     lands, so a manually typed variable blends into text like the inserted
     ones — no more "type it, then leave and come back to see the chip". Only
     the token ending exactly at the caret is converted, and the caret is kept
     right after the new chip so typing flows on. Returns true if it chipified. */
  function maybeChipifyAtCaret() {
    const sel = window.getSelection();
    if (!sel || !sel.rangeCount || !sel.isCollapsed) return false;
    const range = sel.getRangeAt(0);
    const node = range.startContainer;
    if (node.nodeType !== 3 || !ref.current || !ref.current.contains(node)) return false;
    const caret = range.startOffset;
    const before = node.textContent.slice(0, caret);
    const m = before.match(/\{\{\s*([^{}]+?)\s*\}\}$/);   // token closing at the caret
    const name = m && m[1].trim();
    if (!name) return false;

    const start = caret - m[0].length;
    const parent = node.parentNode;
    const afterNode = document.createTextNode(node.textContent.slice(caret));
    const beforeNode = document.createTextNode(node.textContent.slice(0, start));
    const tmp = document.createElement('div');
    tmp.innerHTML = chipHTML(name, varMetaRef.current);
    const chip = tmp.firstChild;

    parent.replaceChild(afterNode, node);
    parent.insertBefore(chip, afterNode);
    if (start > 0) parent.insertBefore(beforeNode, chip);

    const r = document.createRange();
    r.setStart(afterNode, 0); r.collapse(true);
    sel.removeAllRanges(); sel.addRange(r);
    return true;
  }

  /* Drag the corner handle of an inline-attachment block to resize it.
     Width is clamped, painted live on the block, and persisted to the
     variable (onAttachmentResize) on release so the sent <img> matches. */
  function onContentMouseDown(e) {
    const handle = e.target?.closest?.('.gb-rte-att-resize');
    if (!handle) return;
    const block = handle.closest('.gb-rte-att');
    if (!block) return;
    e.preventDefault();
    e.stopPropagation();
    const name = block.getAttribute('data-att') || '';
    const startX = e.clientX;
    const startW = block.offsetWidth;
    const sizeEl = block.querySelector('.gb-rte-att-size');
    let w = startW;
    const move = (ev) => {
      w = Math.max(24, Math.min(600, Math.round(startW + (ev.clientX - startX))));
      block.style.width = w + 'px';
      if (sizeEl) sizeEl.textContent = w + 'px';
    };
    const up = () => {
      document.removeEventListener('mousemove', move);
      document.removeEventListener('mouseup', up);
      if (name && w !== startW) onAttachmentResize?.(name, w);
    };
    document.addEventListener('mousemove', move);
    document.addEventListener('mouseup', up);
  }

  /* Paste — strip Word/Outlook junk, keep basic formatting (incl. bullet
     lists), and convert any {{var}} in the pasted content into live chips so
     pasted variables render immediately instead of as raw braces. stripChips
     first normalizes chips already in the clipboard (e.g. copied from this
     editor) back to {{var}} before re-rendering, so nothing double-wraps. */
  function onPaste(e) {
    e.preventDefault();
    if (singleLine) {
      const text = e.clipboardData.getData('text/plain').replace(/\s+/g, ' ');
      document.execCommand('insertText', false, text);
      saveSelection();
      setEmpty(!ref.current.textContent.trim());
      emit();
      return;
    }
    const html = e.clipboardData.getData('text/html');
    const clean = html
      ? highlightVars(stripChips(sanitizeHtml(html)), varMetaRef.current)
      : highlightVars(plainToHtml(e.clipboardData.getData('text/plain')), varMetaRef.current);
    document.execCommand('insertHTML', false, clean);
    saveSelection();
    setEmpty(!ref.current.textContent.trim());
    emit();
  }

  /* Copy / cut — put the STORED format on the clipboard: chips become their
     {{var}} placeholder (no chip spans or bolt SVG leaking out) and bullet
     lists serialize with "- " markers in the plain-text flavor. Fixes pasting
     variables/bullets into the CRM email or another app coming out "weird".
     Only handles a real (non-collapsed) selection; otherwise defers to the
     browser default. */
  function onCopyCut(e, isCut) {
    const sel = window.getSelection();
    if (!sel || !sel.rangeCount || sel.isCollapsed || !ref.current?.contains(sel.anchorNode)) return;
    const holder = document.createElement('div');
    holder.appendChild(sel.getRangeAt(0).cloneContents());
    try {
      e.clipboardData.setData('text/html', sanitizeHtml(stripChips(holder.innerHTML)));
      e.clipboardData.setData('text/plain', fragToPlain(holder));
      e.preventDefault();
    } catch { return; }   // clipboard API blocked — let the default copy run
    if (isCut) {
      document.execCommand('delete');
      saveSelection();
      setEmpty(!ref.current.textContent.trim());
      emit();
    }
  }

  function onKeyDown(e) {
    if (singleLine && e.key === 'Enter') { e.preventDefault(); return; }
    if (!slashRef.current) return;
    if (e.key === 'Escape') {
      e.preventDefault(); slashSuppressedRef.current = true; slashRef.current = null;
      onSlashQueryChange?.(null); onSlashCancel?.(); return;
    }
    if (e.key === 'ArrowDown' || e.key === 'ArrowUp') {
      e.preventDefault(); onSlashNavigate?.(e.key === 'ArrowDown' ? 1 : -1); return;
    }
    if (e.key === 'Enter' || e.key === 'Tab') {
      e.preventDefault(); onSlashExecute?.(slashRef.current.api); return;
    }
  }

  function slashContext() {
    if (!onSlashQueryChange) return null;
    const sel = window.getSelection();
    if (!sel?.isCollapsed || !sel.rangeCount || !ref.current?.contains(sel.anchorNode)) return null;
    try {
      const before = document.createRange();
      before.selectNodeContents(ref.current);
      before.setEnd(sel.anchorNode, sel.anchorOffset);
      const match = before.toString().match(/(?:^|\s)\/([^\s/]*)$/);
      if (!match || sel.anchorNode.nodeType !== Node.TEXT_NODE) return null;
      const tokenLength = match[1].length + 1;
      if (sel.anchorOffset < tokenLength) return null;
      const range = document.createRange();
      range.setStart(sel.anchorNode, sel.anchorOffset - tokenLength);
      range.setEnd(sel.anchorNode, sel.anchorOffset);
      return { query: match[1], range };
    } catch { return null; }
  }

  function replaceSlashWithStatus(range, label) {
    const span = document.createElement('span');
    span.className = 'gb-rte-slash-status';
    span.contentEditable = 'false';
    span.dataset.state = 'loading';
    span.textContent = `Loading ${label}…`;
    const spacer = document.createTextNode('\u00a0');
    range.deleteContents();
    range.insertNode(spacer);
    range.insertNode(span);
    const caret = document.createRange();
    caret.setStartAfter(spacer); caret.collapse(true);
    const sel = window.getSelection(); sel.removeAllRanges(); sel.addRange(caret);
    slashRef.current = null;
    onSlashQueryChange?.(null);
    setEmpty(false);
    emit();
    return {
      setError(message) {
        if (!span.isConnected) return;
        span.dataset.state = 'error';
        span.textContent = message || 'Template failed';
        emit();
      },
      setText(message) {
        if (!span.isConnected) return;
        const text = document.createTextNode(String(message || ''));
        span.replaceWith(text);
        const caret = document.createRange();
        caret.setStartAfter(text); caret.collapse(true);
        const selection = window.getSelection(); selection.removeAllRanges(); selection.addRange(caret);
        emit();
      },
    };
  }

  function refreshSlashContext() {
    if (slashSuppressedRef.current) return;
    const context = slashContext();
    if (!context) {
      if (slashRef.current) onSlashQueryChange?.(null);
      slashRef.current = null;
      return;
    }
    const api = {
      query: context.query,
      setLoading: (label) => replaceSlashWithStatus(context.range, label),
    };
    slashRef.current = { ...context, api };
    onSlashQueryChange({ query: context.query, api });
  }

  // Clicking a {{variable}} chip (name or bolt) opens its smart-options
  // popover. We pass the chip element AND the cursor position (clientX,
  // clientY) so the caller can spawn the popover either anchored to the
  // chip or — preferred — cursor-anchored via DraggablePopup.
  function onClickContent(e) {
    if (!onChipClick) return;
    const chip = e.target?.closest?.('.gb-rte-chip');
    if (!chip) return;
    const nameEl = chip.querySelector('.gb-rte-chip-name');
    const name   = ((nameEl || chip).textContent || '').replace(/[{}]/g, '').trim();
    if (name) onChipClick(name, chip, { x: e.clientX, y: e.clientY });
  }

  function onInput() {
    // Convert a just-completed {{var}} into a chip in place before emitting,
    // so typed variables blend into the text live (not just on remount).
    if (!singleLine) maybeChipifyAtCaret();
    setEmpty(!ref.current.textContent.trim());
    saveSelection();
    refreshMarks();
    emit();
    slashSuppressedRef.current = false;
    refreshSlashContext();
  }

  const md = fn => e => { e.preventDefault(); fn(); };

  return (
    <div style={{
      border: bare ? 'none' : '1px solid var(--gb-border-default)',
      borderRadius: bare ? 0 : 'var(--gb-r-md)',
      // Clip children to the rounded corners. Without this, the singleLine
      // overflow:auto scroll layer + the body's content paint extend past
      // the wrapper's border-radius and the corners look square.
      overflow: 'hidden',
      background: bare ? 'transparent' : 'var(--gb-surface-canvas)',
    }}>
      {/* ── Toolbar (full mode only) ── */}
      {!singleLine && (
        <div style={{
          position: 'relative',
          padding: sz.toolbarPad,
          background: 'var(--gb-surface-modal)',
          borderBottom: '1px solid var(--gb-border-subtle)',
          borderRadius: 'var(--gb-r-md) var(--gb-r-md) 0 0',
          display: 'flex', alignItems: 'center', flexWrap: 'wrap', gap: 1,
        }}>
          <TBtn sz={sz} icon={<Ic.bold />}      active={marks.bold}      title="Bold"           onMouseDown={md(() => exec('bold'))} />
          <TBtn sz={sz} icon={<Ic.italic />}    active={marks.italic}    title="Italic"         onMouseDown={md(() => exec('italic'))} />
          <TBtn sz={sz} icon={<Ic.underline />} active={marks.underline} title="Underline"      onMouseDown={md(() => exec('underline'))} />
          <TBtn sz={sz} icon={<Ic.strike />}    active={marks.strike}    title="Strikethrough"  onMouseDown={md(() => exec('strikeThrough'))} />
          <Sep sz={sz} />
          <TBtn sz={sz} icon={<Ic.alignL />} title="Align left"   onMouseDown={md(() => exec('justifyLeft'))} />
          <TBtn sz={sz} icon={<Ic.alignC />} title="Align center" onMouseDown={md(() => exec('justifyCenter'))} />
          <TBtn sz={sz} icon={<Ic.alignR />} title="Align right"  onMouseDown={md(() => exec('justifyRight'))} />
          <Sep sz={sz} />
          <TBtn sz={sz} icon={<Ic.ul />} title="Bullet list"   onMouseDown={md(() => exec('insertUnorderedList'))} />
          <TBtn sz={sz} icon={<Ic.ol />} title="Numbered list" onMouseDown={md(() => exec('insertOrderedList'))} />
          <TBtn sz={sz} icon={<Ic.link />} title="Insert link"  onMouseDown={md(() => {
            const url = window.prompt('Link URL:', 'https://');
            if (url) exec('createLink', url);
          })} />
          <Sep sz={sz} />
          <ColorButton
            title="Text color"
            value={textColor}
            width={sz.btnW} height={sz.btnH}
            onMouseDown={saveSelection}
            onChange={(c) => { setTextColor(c); exec('foreColor', c); }}
          />
          <ColorButton
            variant="fill"
            title="Highlight color"
            value={bgColor}
            width={sz.btnW} height={sz.btnH}
            onMouseDown={saveSelection}
            onChange={(c) => { setBgColor(c); exec('hiliteColor', c); }}
          />
          <TBtn sz={sz} icon={<Ic.clear />} title="Clear formatting" onMouseDown={md(() => exec('removeFormat'))} />

          {variables.length > 0 && (
            <>
              <div style={{ flex: 1 }} />
              <button
                ref={varBtnRef}
                type="button"
                onMouseDown={e => { e.preventDefault(); saveSelection(); setVarMenu(v => !v); }}
                style={{
                  height: sz.varH, padding: '0 7px', borderRadius: 4, border: 'none', cursor: 'pointer',
                  background: varMenu ? 'var(--gb-brand-tint-medium)' : 'var(--gb-fill-subtle)',
                  color: 'var(--gb-brand-label)',
                  display: 'inline-flex', alignItems: 'center', gap: 4,
                  fontSize: sz.varFont, fontWeight: 700,
                }}
              >
                <Ic.bolt size={sz.varIcon} /> Variable
              </button>
              {varMenu && (
                <VarMenu anchorRef={varBtnRef} variables={variables} onPick={insertVariable} onClose={() => setVarMenu(false)} />
              )}
            </>
          )}
        </div>
      )}

      {/* ── Editable surface ── */}
      <div style={{ position: 'relative' }}>
        {empty && placeholder && (
          <span className="gb-rte-ph" style={{
            top:  singleLine ? sz.phLine.top  : sz.phFull.top,
            left: singleLine ? sz.phLine.left : sz.phFull.left,
            fontSize: singleLine ? sz.phLine.font : sz.phFull.font,
          }}>{placeholder}</span>
        )}
        <div
          ref={ref}
          className="gb-rte-content"
          contentEditable
          suppressContentEditableWarning
          onInput={onInput}
          onPaste={onPaste}
          onCopy={(e) => onCopyCut(e, false)}
          onCut={(e) => onCopyCut(e, true)}
          onKeyDown={onKeyDown}
          onClick={onClickContent}
          onMouseDown={onContentMouseDown}
          onKeyUp={() => { saveSelection(); refreshMarks(); refreshSlashContext(); }}
          onMouseUp={() => { saveSelection(); refreshMarks(); }}
          onBlur={saveSelection}
          style={{
            padding: singleLine ? sz.slPad : sz.pad,
            minHeight: singleLine ? 'auto' : bodyMinH,
            fontSize: singleLine ? sz.slFont : sz.font,
            fontWeight: singleLine ? 600 : 400,
            lineHeight: 1.6,
            color: 'var(--gb-text-primary)',
            fontFamily: 'var(--gb-font-sans)',
            whiteSpace: singleLine ? 'nowrap' : 'pre-wrap',
            overflowX: singleLine ? 'auto' : 'visible',
          }}
        />
      </div>

      {/* ── Inline variable inserter for single-line mode ── */}
      {singleLine && variables.length > 0 && (
        <SingleLineVarBar variables={variables} onPick={insertVariable} onOpen={saveSelection} />
      )}
    </div>
  );
}

/* ── Variable dropdown menu (full-mode toolbar) ─────────────── */
function VarMenu({ variables, onPick, onClose, anchorRef }) {
  // Position from the anchor's viewport rect — portaled to body so the
  // wrapper's `overflow: hidden` (which rounds the editor's corners)
  // doesn't clip the dropdown.
  const [pos, setPos] = useState(null);
  useEffect(() => {
    function update() {
      const el = anchorRef?.current;
      if (!el) return;
      const r = el.getBoundingClientRect();
      setPos({ top: r.bottom + 4, right: window.innerWidth - r.right });
    }
    update();
    window.addEventListener('resize', update);
    return () => window.removeEventListener('resize', update);
  }, [anchorRef]);

  useEffect(() => {
    const h = () => onClose();
    const t = setTimeout(() => document.addEventListener('mousedown', h), 0);
    return () => { clearTimeout(t); document.removeEventListener('mousedown', h); };
  }, [onClose]);

  if (!pos) return null;
  return createPortal(
    <div
      className="gb-rte-portal"
      data-gb-scale="popovers"
      onMouseDown={e => e.stopPropagation()}
      style={{
        position: 'fixed', top: pos.top, right: pos.right, zIndex: 2147483400,
        minWidth: 170, maxHeight: 220, overflowY: 'auto',
        background: 'var(--gb-surface-2)',
        border: '1px solid var(--gb-border-default)',
        borderRadius: 'var(--gb-r-md)',
        boxShadow: 'var(--gb-shadow-modal)', padding: 4,
      }}
    >
      {variables.map(v => (
        <button
          key={v.name} type="button"
          onMouseDown={e => { e.preventDefault(); onPick(v.name); }}
          style={{
            width: '100%', textAlign: 'left', border: 'none', cursor: 'pointer',
            padding: '6px 8px', borderRadius: 5, background: 'transparent',
            color: 'var(--gb-text-secondary)', fontFamily: 'var(--gb-font-mono)',
            fontSize: 11, fontWeight: 600,
          }}
          onMouseEnter={e => { e.currentTarget.style.background = 'var(--gb-fill-subtle)'; }}
          onMouseLeave={e => { e.currentTarget.style.background = 'transparent'; }}
        >
          {`{{${v.name}}}`}
        </button>
      ))}
    </div>,
    document.body,
  );
}

/* ── Variable chips row under a single-line field ───────────── */
function SingleLineVarBar({ variables, onPick, onOpen }) {
  return (
    <div style={{
      display: 'flex', flexWrap: 'wrap', gap: 4,
      padding: '6px 8px',
      borderTop: '1px solid var(--gb-border-subtle)',
      background: 'var(--gb-surface-modal)',
      borderRadius: '0 0 var(--gb-r-md) var(--gb-r-md)',
    }}>
      {variables.map(v => (
        <button
          key={v.name} type="button"
          onMouseDown={e => { e.preventDefault(); onOpen(); onPick(v.name); }}
          style={{
            border: '1px solid var(--gb-brand-tint-border)',
            background: 'var(--gb-brand-tint-soft)',
            color: 'var(--gb-brand-label)',
            borderRadius: 4, padding: '1px 6px', cursor: 'pointer',
            fontFamily: 'var(--gb-font-mono)', fontSize: 10, fontWeight: 600,
          }}
        >
          {`{{${v.name}}}`}
        </button>
      ))}
    </div>
  );
}
